static const voice_clip_t VOICE_CLIPS[VOICE_PHRASE_COUNT] = {
    [ VOICE_ONLINE ] = { "CELESTIAL ONLINE", VOICE_ONLINE_DATA, 30472 },
    [ VOICE_READY ] = { "SYSTEM READY", VOICE_READY_DATA, 16942 },
    [ VOICE_ORACLE ] = { "ORACLE ACTIVATED", VOICE_ORACLE_DATA, 29682 },
    [ VOICE_WARNING ] = { "ANOMALY DETECTED", VOICE_WARNING_DATA, 36578 },
};

    const voice_clip_t* voice_get_clip(voice_phrase_id_t id) {
        if ((unsigned)id < VOICE_PHRASE_COUNT) {
            return &VOICE_CLIPS[id];
        }
        return NULL;
    }
